<?php require __DIR__ . '/vendor/autoload.php'; $dotenv = Dotenv\Dotenv::createImmutable(__DIR__); $dotenv->load(); require __DIR__ . '/config/config.php'; require __DIR__ . '/app/Core/Database.php'; $db = App\Core\Database::getInstance(); $stmt = $db->query('SELECT id, extra_files FROM quote_requests WHERE extra_files IS NOT NULL AND extra_files != '''''' ORDER BY id DESC LIMIT 5'); $rows = $stmt->fetchAll(PDO::FETCH_ASSOC); foreach ($rows as $row) { echo 'ID: ' . $row['id'] . PHP_EOL; echo 'Raw: ' . $row['extra_files'] . PHP_EOL; $decoded = json_decode($row['extra_files'] ?? 'null', true); echo 'Decoded: '; var_dump($decoded); echo '------------' . PHP_EOL; }
